<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Application\Policy\Allow\Disable;

use Throwable;
use Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Disable\SnippetDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedDisableAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(SnippetDisableAllowDecision $proposal): SnippetDisableAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedDisableAllow Snippet");
        $span = $this->startSpan("Check IsAuthenticatedDisableAllow Snippet");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if ($userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedDisable');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
